use crate::*;
use crate::owned::{NativeReceiveMap,NativeMappedReceiver};
use crate::{DslValue,retained_clone::RetainedCloneSource,retirement::controlled::ControlledRetirement};
#[derive(crate::RetireOwned)]#[value(crate="crate")]
struct Wrapped(String);
impl NativeReceiveMap<String> for Wrapped{fn from_native(value:String)->Self{Self(value)}}
struct Bank{remaining:RetainedCloneGrant,fuel:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("🎟️work/📐️.json")).unwrap();Self{remaining:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:f["fuel"].as_u64().unwrap()}}fn offer(&self)->RetainedCloneGrant{assert!(self.fuel>0);RetainedCloneGrant{maximum_items:self.remaining.maximum_items.min(1),maximum_copy_bytes:self.remaining.maximum_copy_bytes.min(4096),..self.remaining}}fn quoted(&self,d:RetirementDemand)->RetainedCloneGrant{let loan=self.offer();assert!(crate::retained_clone::retained_clone_grant_admits(loan,d));RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..loan}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.remaining));self.remaining.maximum_items-=p.copied_items;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();}}
fn actual<R>(run:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(run)}
fn check(p:RetainedCloneProgress,h:(usize,usize),g:RetainedCloneGrant){assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),h)}
fn drain<T:RetireOwned>(value:T,bank:&mut Bank){let mut close=ControlledRetirement::new(value).map_err(|(error,_)|error).unwrap();for _ in 0..100000{if close.terminal_is_empty(){return}let g=bank.quoted(close.next_demand(4096).unwrap());let(step,h)=actual(||close.step(g));let work=close.last_turn_work();let p=step.unwrap().progress();check(p,h,g);bank.post(p,work);}panic!("original native map cleanup stalled")}
fn check_mapping<I:crate::owned::tree::NativeValueSource+?Sized+'static>(project:for<'a>fn(RetainedCloneRef<'a,DslValue>)->RetainedCloneRef<'a,I>){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🔄️map/🧪️tests/🔣️.json")).unwrap();let text=law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let oracle:serde_json::Value=serde_json::from_str(&serde_json::to_string(&text).unwrap()).unwrap();
 for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize)).chain([None]){
  let mut bank=Bank::new();let original=DslValue::String(text.clone());let mut source=crate::source_fixture::capture(original,&mut bank,Bank::offer,|bank,p,work,h,g|{check(p,h,g);bank.post(p,work)});
  let(mut receiver,h)=actual(NativeMappedReceiver::<I,String,Wrapped>::new);assert_eq!(h,(0,0));
  let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);
  for turn_index in 0..100000{if cut==Some(turn_index)||receiver.output_ready(){break}let d=receiver.demands(project(source.borrow()),4096).unwrap();let g=bank.quoted(d);assert!(crate::retained_clone::retained_clone_grant_admits(g,d));
   for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,h)=actual(||receiver.advance(project(source.borrow()),&mut control,4096,denied));assert_eq!(turn.work,0);let p=turn.result.unwrap().progress();check(p,h,denied);assert_eq!(p,Default::default());assert_eq!(receiver.demands(project(source.borrow()),4096).unwrap(),d);}
   let(turn,h)=actual(||receiver.advance(project(source.borrow()),&mut control,4096,g));let work=turn.work;let p=turn.result.unwrap().progress();check(p,h,g);assert!(work>0||p!=Default::default());bank.post(p,work);assert!(turn_index<99999);
  }
  if cut.is_none(){assert!(receiver.output_ready());let d=receiver.take_demand().unwrap();let g=bank.quoted(d);assert_eq!(d.copy_bytes,std::mem::size_of::<Wrapped>());let(turn,h)=actual(||receiver.take(RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));assert!(receiver.output_ready());let(turn,h)=actual(||receiver.take(RetainedCloneGrant{maximum_copy_bytes:0,..g}));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));let(turn,h)=actual(||receiver.take(g));let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();check(p,h,g);bank.post(p,work);assert_eq!(serde_json::Value::String(output.0.clone()),oracle);drain(output,&mut bank);}
  receiver.begin_close();for turn_index in 0..100000{if receiver.terminal_is_empty(){break}let g=bank.quoted(receiver.close_demands(4096).unwrap());let(turn,h)=actual(||receiver.close_step(g));let work=turn.work;let p=turn.result.unwrap().progress();check(p,h,g);assert!(work>0||p!=Default::default());bank.post(p,work);assert!(turn_index<99999);}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..100000{if source.terminal_is_empty(){break}let g=bank.quoted(source.next_close_demand(4096).unwrap());let(turn,h)=actual(||source.close_step(g));let work=turn.work;let p=turn.result.unwrap().progress();check(p,h,g);bank.post(p,work);}assert!(source.terminal_is_empty());
 }
}
#[test]fn native_mapping_preserves_completed_original_text_and_every_cancelled_child(){check_mapping::<DslValue>(|input|input);check_mapping::<dyn crate::owned::tree::NativeValueSource>(|input|input.project(0,|source|source as &dyn crate::owned::tree::NativeValueSource));}
